#!/usr/bin/env node
// Generated by Squad from the Squad SDK (claude-plugin.ts). Do not edit: run `node scripts/build-claude-plugin.mjs`.
//
// Squad plugin launcher. Runs the Squad CLI with this process's arguments, resolved in this order:
//   1. SQUAD_CLI (a command, or a .js entry run with this Node)
//   2. the project's own install: node_modules/@bradygaster/squad-cli
//   3. a `squad` on PATH (never this plugin's own bin/)
//   4. npx -y @bradygaster/squad-cli@<this plugin's version>, only when SQUAD_ALLOW_NPX=1: it downloads and runs
//      code, so it is opt-in. Without it, the launcher fails with install instructions.
// 2 and 3 are skipped when their version is older than this plugin's: an older CLI lacks commands the
// plugin calls (`dashboard`, `hook --plugin`). The version is read from package.json, BUNDLE-INFO.json
// (standalone bundles), or an embedded node_modules. A CLI whose version cannot be read is used as found.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PKG = '@bradygaster/squad-cli';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ownBin = path.join(root, 'bin');
const win = process.platform === 'win32';

function canonical(file) {
  const resolved = fs.realpathSync(file);
  return win ? resolved.toLowerCase() : resolved;
}

// Hooks must be cheap no-ops outside an opted-in team, before CLI or npx resolution.
function hooksEnabled() {
  let project = path.resolve(process.env.CLAUDE_PROJECT_DIR || process.cwd());
  for (;;) {
    for (const name of ['.squad', '.ai-team']) {
      const local = path.join(project, name);
      if (!fs.existsSync(local)) continue;
      try {
        let config = JSON.parse(fs.readFileSync(path.join(local, 'config.json'), 'utf8'));
        if (typeof config.version === 'number' && typeof config.teamRoot === 'string' && config.teamRoot !== '.') {
          const team = path.resolve(project, config.teamRoot);
          const candidates = [path.join(team, name), path.join(team, name === '.squad' ? '.ai-team' : '.squad'), team];
          const dir = candidates.find((candidate) => fs.existsSync(path.join(candidate, 'config.json')));
          if (!dir) return false;
          config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf8'));
        }
        return config.claudeHooks === 'advisory';
      } catch {
        return false;
      }
    }
    const parent = path.dirname(project);
    if (parent === project) return false;
    project = parent;
  }
}

if (process.argv[2] === 'hook' && process.argv[3] === 'claude' && !hooksEnabled()) process.exit(0);

function pluginVersion() {
  try {
    return JSON.parse(fs.readFileSync(path.join(root, '.claude-plugin', 'plugin.json'), 'utf8')).version;
  } catch {
    return undefined;
  }
}

/** The version of the Squad CLI behind `entry` (a script, symlink or npm shim), if it can be found. */
function cliVersion(entry) {
  try {
    let dir = path.dirname(fs.realpathSync(entry));
    for (let i = 0; i < 8; i++) {
      // npm's Windows shims sit beside node_modules rather than linking into it.
      for (const file of [path.join(dir, 'package.json'), path.join(dir, 'node_modules', ...PKG.split('/'), 'package.json')]) {
        if (!fs.existsSync(file)) continue;
        const pkg = JSON.parse(fs.readFileSync(file, 'utf8'));
        if (pkg.name === PKG) return pkg.version;
      }
      // Standalone bundle: BUNDLE-INFO.json or app/node_modules/<pkg>/package.json.
      try {
        const info = path.join(dir, 'BUNDLE-INFO.json');
        if (fs.existsSync(info)) {
          const v = JSON.parse(fs.readFileSync(info, 'utf8')).squadVersion;
          if (v) return v;
        }
      } catch { /* skip */ }
      try {
        const nested = path.join(dir, 'app', 'node_modules', ...PKG.split('/'), 'package.json');
        if (fs.existsSync(nested)) {
          const pkg = JSON.parse(fs.readFileSync(nested, 'utf8'));
          if (pkg.name === PKG) return pkg.version;
        }
      } catch { /* skip */ }
      const up = path.dirname(dir);
      if (up === dir) break;
      dir = up;
    }
  } catch {
    // unreadable: treat the version as unknown
  }
  return undefined;
}

/** Semver precedence, prerelease included: true when `a` sorts before `b`. */
function older(a, b) {
  const split = (v) => {
    const s = String(v).split('+')[0];
    const i = s.indexOf('-');
    return [(i < 0 ? s : s.slice(0, i)).split('.').map(Number), i < 0 ? [] : s.slice(i + 1).split('.')];
  };
  const [ac, ap] = split(a);
  const [bc, bp] = split(b);
  for (let i = 0; i < 3; i++) if ((ac[i] || 0) !== (bc[i] || 0)) return (ac[i] || 0) < (bc[i] || 0);
  if (!ap.length || !bp.length) return ap.length > bp.length;
  for (let i = 0; i < Math.min(ap.length, bp.length); i++) {
    if (ap[i] === bp[i]) continue;
    const an = /^\d+$/.test(ap[i]);
    const bn = /^\d+$/.test(bp[i]);
    if (an && bn) return Number(ap[i]) < Number(bp[i]);
    if (an !== bn) return an;
    return ap[i] < bp[i];
  }
  return ap.length < bp.length;
}

/** False only for a CLI known to be older than this plugin. */
function recentEnough(entry, version) {
  const found = cliVersion(entry);
  return !found || !version || !older(found, version);
}

function onPath(name) {
  const exts = win ? (process.env.PATHEXT || '.EXE;.CMD;.BAT').split(';') : [''];
  for (const dir of (process.env.PATH || '').split(path.delimiter)) {
    if (!dir) continue;
    try {
      if (canonical(dir) === canonical(ownBin)) continue;
    } catch { continue; }
    for (const ext of exts) {
      const file = path.join(dir, name + ext);
      try {
        if (fs.statSync(file).isFile()) return file;
      } catch {
        // not here
      }
    }
  }
  return undefined;
}

function resolveCli() {
  const override = process.env.SQUAD_CLI;
  if (override) return /\.[cm]?js$/.test(override) ? [process.execPath, [override]] : [override, []];
  const version = pluginVersion();
  const project = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const local = path.join(project, 'node_modules', ...PKG.split('/'), 'dist', 'cli-entry.js');
  if (fs.existsSync(local) && recentEnough(local, version)) return [process.execPath, [local]];
  const global = onPath('squad');
  if (global && recentEnough(global, version)) return [global, []];
  const want = version ? `${PKG}@${version}` : PKG;
  if (/^(1|true|yes)$/i.test(process.env.SQUAD_ALLOW_NPX || '')) return [win ? 'npx.cmd' : 'npx', ['-y', want]];
  throw new Error(
    `no Squad CLI${version ? ` ${version} or newer` : ''} found (looked at SQUAD_CLI, this project's node_modules and PATH). ` +
      `Install it with: npm install -g ${want}. Or set SQUAD_ALLOW_NPX=1 to let the plugin download and run it with npx.`,
  );
}

// npm's .cmd shims cannot safely forward arbitrary argv through cmd.exe. Run their JS entry instead.
function withoutShell(command, prefix) {
  if (!win || !/\.(cmd|bat)$/i.test(command)) return [command, prefix];
  const shim = path.isAbsolute(command) ? command : onPath(path.basename(command, path.extname(command)));
  const dir = shim ? path.dirname(shim) : path.dirname(process.execPath);
  const candidates = path.basename(command).toLowerCase() === 'npx.cmd'
    ? [path.join(dir, 'node_modules/npm/bin/npx-cli.js'), path.join(path.dirname(process.execPath), 'node_modules/npm/bin/npx-cli.js')]
    : [path.join(dir, 'node_modules', ...PKG.split('/'), 'dist/cli-entry.js')];
  const entry = candidates.find((candidate) => fs.existsSync(candidate));
  if (!entry) throw new Error(`Cannot resolve the JavaScript entry for ${command}; set SQUAD_CLI to cli-entry.js`);
  return [process.execPath, [entry, ...prefix]];
}

let command, prefix;
try {
  [command, prefix] = withoutShell(...resolveCli());
} catch (err) {
  process.stderr.write(`squad plugin: ${err.message}\n`);
  process.exit(1);
}
const child = spawn(command, [...prefix, ...process.argv.slice(2)], {
  stdio: 'inherit',
  shell: false,
});
for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(signal, () => child.kill(signal));
child.on('error', (err) => {
  process.stderr.write(`squad plugin: cannot start the Squad CLI (${err.message}). Install it with: npm install -g ${PKG}\n`);
  process.exit(1);
});
child.on('exit', (code, signal) => process.exit(code ?? (signal ? 1 : 0)));
